---
name: pr-triage

on:
  pull_request_target:
    types: [opened]

permissions: {}

jobs:
  triage:
    name: Welcome and label
    runs-on: ubuntu-latest
    timeout-minutes: 5
    # pull-requests:write comments on and labels the pull request; issues:write is required
    # separately because creating a repository label is an Issues-API operation.
    permissions:
      pull-requests: write
      issues: write
    steps:
      - name: Welcome contributor and apply needs-triage label
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        env:
          PR_AUTHOR: ${{ github.event.pull_request.user.login }}
          PR_TITLE: ${{ github.event.pull_request.title }}
        with:
          script: |
            const author = process.env.PR_AUTHOR;
            const title = process.env.PR_TITLE;
            const { owner, repo } = context.repo;
            const issue_number = context.issue.number;
            const label = "needs-triage";

            await github.rest.issues.createComment({
              owner,
              repo,
              issue_number,
              body: `Welcome, @${author}! Thanks for opening **${title}**.`,
            });

            try {
              await github.rest.issues.createLabel({ owner, repo, name: label });
            } catch (error) {
              if (error.status !== 422) throw error; // label already exists
            }

            await github.rest.issues.addLabels({ owner, repo, issue_number, labels: [label] });

